<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Users','subtitle'=>'Create and maintain Admin, Barangay Official, and Borrower accounts.']) ?><div class="grid-2 uneven"><section class="panel"><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Contact</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><b><?= esc($u['display_name']) ?></b><small>@<?= esc($u['username']) ?></small></td><td><?= esc(role_label($u['role'])) ?></td><td><?= esc($u['email']?:'—') ?><small><?= esc($u['contact_number']?:'') ?></small></td><td><?= view('partials/status_badge',['status'=>$u['status']]) ?></td><td class="actions"><button class="btn small ghost" type="button" data-dialog-open="user-<?= (int)$u['id'] ?>">Edit</button><?php if((int)$u['id']!==$this->userId()): ?><form method="post" action="<?= site_url('users/'.$u['id'].'/status') ?>" data-confirm="<?= esc(($u['status']==='active'?'Deactivate ':'Activate ').$u['display_name'].'?', 'attr') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $u['status']==='active'?'inactive':'active' ?>"><button class="btn small" type="submit"><?= $u['status']==='active'?'Deactivate':'Activate' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php foreach($users as $u): ?><dialog class="form-dialog" id="user-<?= (int)$u['id'] ?>"><div class="dialog-head"><h2>Edit <?= esc($u['display_name']) ?></h2><button type="button" data-dialog-close aria-label="Close"><?= ui_icon('x') ?></button></div><form method="post" action="<?= site_url('users/'.$u['id']) ?>" class="stack-form"><?= csrf_field() ?><label>Display Name<input name="display_name" value="<?= esc($u['display_name']) ?>" required></label><label>Email<input type="email" name="email" value="<?= esc($u['email']??'') ?>"></label><label>Contact Number<input name="contact_number" value="<?= esc($u['contact_number']??'') ?>"></label><label>Address<textarea name="address" rows="2"><?= esc($u['address']??'') ?></textarea></label><label>Role<select name="role"><?php foreach(config('BantayGamit')->roles as $k=>$v): ?><option value="<?= esc($k) ?>" <?= $u['role']===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="active" <?= $u['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $u['status']==='inactive'?'selected':'' ?>>Inactive</option></select></label><label>New Password <small>Leave blank to keep current password</small><input type="password" name="password" minlength="8"></label><div class="form-actions"><button class="btn" type="button" data-dialog-close>Cancel</button><button class="btn primary" type="submit">Save Changes</button></div></form></dialog><?php endforeach; ?><aside class="panel action-panel"><h2>Create Account</h2><form method="post" action="<?= site_url('users') ?>" class="stack-form"><?= csrf_field() ?><label>Username<input name="username" required value="<?= esc(old('username')) ?>"></label><label>Display Name<input name="display_name" required value="<?= esc(old('display_name')) ?>"></label><label>Email<input type="email" name="email" value="<?= esc(old('email')) ?>"></label><label>Contact Number<input name="contact_number" value="<?= esc(old('contact_number')) ?>"></label><label>Address<textarea name="address" rows="2"><?= esc(old('address')) ?></textarea></label><label>Role<select name="role"><option value="borrower">Borrower</option><option value="barangay_official">Barangay Official</option><option value="admin">Administrator</option></select></label><label>Temporary Password<input type="password" name="password" minlength="8" required></label><input type="hidden" name="status" value="active"><button class="btn primary wide" type="submit">Create User</button></form></aside></div><?= $this->endSection() ?>
